@module routingManager  src=routingManager.lua  loc=1080  mode=chunk  self=rm
@deps ds

# Invariants & contracts
  @invariant  id is a track/fx GUID string — opaque to callers, stable across reload  @ 3
  @invariant  stateless; fx/bus meta are project-scope ds keys, so they ride ds's undo mirror  @ 4
  @invariant  non-native record fields are metadata; rm persists them (see docs/routingManager.md)  @ 5

# Shapes
  @shape  fx = { id=guid, ident=string, fxType=string, name=string, ins=int, outs=int, inNames={str,...}, outNames={str,...}, pinMaps={ins={[port]={pair,...}}, outs=...}, midi={inBus,outBus,inDisabled,outDisabled} }  -- ident JS-normalised; midi only for VST/AU/CLAP; rm:fx adds trackId  @ 335
  @shape  send = { to=guid, kind='audio'|'midi', gain=number, srcChan=int, dstChan=int, pos='preFx'|'preFader'|'postFader' }  -- track output routing; no id  @ 429

# Imports
  @require util = 'util'  @ 7

