  @state installedFxCache = nil  @ 15   -- reaper's installed-FX set is fixed at runtime
  @state BANK2 = 0x1000000  @ 54
  @state midiCache = {}  @ 149
      @invariant  midiCache[fxGuid]=midi; serves reads, gates no-op writes, pruned when fx leaves  @ 146
  @state b64alpha = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123...  @ 170
  @state b64dec = {}  @ 171
  @state SENDMODE_TO_POS = { [0] = 'postFader', [1] = 'preFx', [3] = 'preFader' }  @ 433
  @state POS_TO_SENDMODE = { postFader = 0, preFx = 1, preFader = 3 }  @ 434
  @state AUTO_BUS = 126  @ 438
  @state TRACK_NATIVE = {  @ 548
  @state FX_NATIVE = {  @ 553
  @state META_PEXT = 'P_EXT:ctm_meta'  @ 559
  @state META_KEY = { fx = 'fxMeta', bus = 'busMeta' }  @ 563
  @state paramIdxByIdent = {}  @ 695

# Private functions
  -- track resolution
  @fn locateTrack(id)  @ 21-28
      -- Stable under reordering. Master matched first since it is absent
      -- from the project-track list.
  -- fx resolution
  @fn locateFx(id)  @ 32-45
  -- pin maps
  @fn decodePairList(track, fxIdx, isoutput, port)  @ 57-74
      -- Adjacent set bits collapse to one pair; the two pins of a port are OR'd together.
  @fn readPinMaps(track, fxIdx)  @ 77-88
      -- ports = pins/2; disconnected ports (zero mask) dropped — absent ⇒ disconnected.
  @fn pinName(track, fxIdx, dir, pin)  @ 90-93
  @fn portNames(track, fxIdx, dir, pinCount)  @ 97-107
      -- Port P (1-indexed) groups pins 2(P-1) and 2P-1. "Sidechain L" + "Sidechain R"
      -- collapse to "Sidechain"; a mismatched pair keeps the left pin's name.
  @fn pinMaskFor(pairList, pinOffset, bankIdx)  @ 110-119
      -- lo/hi for one bank: channels outside this bank's 64-wide window contribute nothing.
  @fn writePinMaps(track, fxIdx, pm)  @ 122-139
      -- Full-replace per fx: ports absent from `pm` are disconnected (zero mask).
  -- per-fx midi routing
  @fn pruneMidiCache(tracks)  @ 151-159
  @fn midiUnchanged(cached, want)  @ 162-168
      -- True iff the cache already holds want's fields, so a chunk read-modify-write would be a no-op.
  @fn b64decode(s)  @ 174-192
  @fn b64encode(s)  @ 194-212
  @fn splitChunkLines(s)  @ 214-220
  @fn joinChunkLines(lines, hasTrailing)  @ 222-224
  @fn findFxBlock(lines, fxIdx)  @ 228-248
      -- Locate the (fxIdx+1)-th non-JS FX block (0-indexed). Returns
      -- (firstBase64LineIdx, trailerLineIdx) or nil.
  @fn mutateByteInBase64Line(line, byteIdx, fn)  @ 252-263
      -- Decode line → mutate one byte via fn → re-encode iff changed.
      -- No-op preserves the line byte-for-byte (round-trip invariant).
  @fn fxBlockStream(lines, firstIdx, lastIdx)  @ 267-276
      -- Concatenate the FX block's base64 content lines into the decoded stream;
      -- nested <...> elements and non-base64 lines are skipped.
  @fn patchStreamByte(lines, firstIdx, lastIdx, off, fn)  @ 280-294
      -- Patch the byte at 1-indexed stream offset `off` via `fn`, re-encoding only
      -- the base64 line it falls in. Returns true if the offset was in range.
  @fn setFXMidiRouting(chunk, fxIdx, opts, pinChannels)  @ 298-316
      -- Per-FX MIDI routing = the decoded stream's last 4 bytes <flags><inBus><outBus>00;
      -- flags are mirrored at head offset 27+8*pinChannels too. See docs/reaper_midi_routing.md.
  @fn readFXMidiRouting(lines, fxIdx)  @ 320-331
      -- Read the fxIdx-th non-JS FX block's routing from the stream's last 4 bytes.
      -- Returns { inBus, outBus, inDisabled, outDisabled } or nil if absent.
  -- fx read
  @fn fxName(track, idx)  @ 338-343
      -- Display name: a user instance rename wins, else the plugin's own name.
  @fn fxTypeAt(track, idx)  @ 345-348
  @fn jsIdent(ident)  @ 352-355
      -- REAPER hands JSFX idents as bare paths ('utility/volume') from fx_ident and
      -- EnumInstalledFX; JS keys on a 'JS:' prefix (CU_IDENT, isJS, readJSFXContent).
  @fn fxIdentAt(track, idx, fxType)  @ 357-361
  @fn isRoutingFx(fxType)  @ 365-368
      -- A routing-bearing FX carries a per-FX MIDI routing record in the chunk — exactly
      -- the <VST>/<CLAP>/<AU> blocks findFxBlock walks. JS, containers, video have none.
  @fn readFx(track, idx)  @ 370-385
  @fn midiFromLines(lines, routingIdx)  @ 389-394
      -- Absent trailer ⇒ passthrough defaults; the field is present for every non-JS
      -- fx so callers can read routing without a JS-vs-not branch.
  @fn readMidiRouting(chunk, routingIdx)  @ 396-399
  @fn readFxChain(track)  @ 404-425
      -- The chunk read serialises the track's whole state (giant-VST presets dominate); its only
      -- unique payload is 4 routing bytes per fx. Read it only when a routing fx GUID is uncached;
      -- otherwise reuse midiCache. see docs/wiringManager.md § Per-FX MIDI routing.
  -- sends
  @fn sendKind(track, sendIdx)  @ 442-445
      -- A send is midi-only iff its audio source is disabled (I_SRCCHAN == -1);
      -- anything else (audio-only, or a dual-stream send) reads as 'audio'.
  @fn readSendChans(track, sendIdx, kind)  @ 449-457
      -- Audio sends carry channels in I_SRCCHAN/I_DSTCHAN; midi sends pack them into
      -- I_MIDIFLAGS (bits 14/22, +1-biased — 0 means all channels).
  @fn readSend(track, sendIdx)  @ 460-474
      -- One decoder behind read, the reconcile diff, and the gain-drift pass.
  @fn readSends(track)  @ 476-482
  @fn sendKey(s)  @ 485-487
      -- Identity tuple — gain is the mutable value, deliberately absent.
  @fn createSend(track, w)  @ 489-504
  @fn reconcileSends(track, sends)  @ 508-542
      -- Full-replace: drop/create by sendKey identity, then a separate gain pass
      -- because REAPER indices shift under deletion and gains move with the key.
  -- metadata
  @fn decodeBlob(raw)  @ 565-567
  @fn readTrackMeta(track)  @ 569-572
  @fn writeTrackMeta(track, meta)  @ 576-580
      -- Patch-merge so a partial write (just pos) never wipes a sibling (split);
      -- util.REMOVE clears a field.
  @fn readMeta(store)  @ 582-584
  @fn writeMeta(store, id, meta)  @ 587-597
      -- nil meta deletes the entry; otherwise patch-merge (util.REMOVE clears a field).
  -- Mute: clear live pins on one side, stash the real pinout in fx-meta so reads stay wired.
  @fn applyMuteReport(fx)  @ 604-610
      -- A muted fx reads its live (cleared) side, so swap the stashed real pinout back
      -- into it. Mutates and returns the meta-folded record.
  @fn divertIfMuted(fxId, pm)  @ 614-621
      -- A pin write to a muted fx must not relight it: stash the intended pinout for the
      -- cleared side and return a pinMap with that side cleared, keeping the fx silent.
  -- read
  @fn trackName(track)  @ 625-628
  @fn readMainSend(track)  @ 630-638
  @fn trackHasMidiTake(track)  @ 642-648
      -- A track's own active MIDI take decides whether its source node emits on bus 0: a folder
      -- parent or bare source with no midi take produces nothing there (the out stays wirable).
  @fn readTrack(track, isMaster)  @ 650-665
  @fn stampParents(records)  @ 669-679
      -- Folder membership is positional (I_FOLDERDEPTH: 1 opens, <0 closes |n|): walk
      -- tracks in order, each foldered track's parent is the open-folder stack top.
  -- write
  @fn writeMainSend(track, ms)  @ 683-691
  @fn paramsByName(track, fxIdx)  @ 697-710
  @fn writeParams(track, fxIdx, params)  @ 713-720
      @contract  params keyed by display name; an unknown name raises  @ 712
  @fn readParams(track, fxIdx)  @ 723-729
      -- Live { [name] = value } for every named param — the read counterpart to writeParams.
  @fn routingIdxOf(track, fxIdx)  @ 733-740
      -- Absolute fx index → chunk routing index (routing-bearing blocks only); nil for a
      -- JS/container fx, which has no routing trailer — writing midi to one is a no-op.
  @fn writeMidiRouting(track, fxIdx, midi)  @ 742-758
  @fn writeTrackFields(track, t)  @ 760-769

# Public API (rm:*)
  @api rm:trackLabels()  @ 774-786
      @contract  lightweight {id, name, number, isMaster} per project track + master; no fx/sends/chunk reads.  @ 773
  @api rm:tracks()  @ 788-802
  @api rm:track(id)  @ 805-812
      @contract  full record for one track by id (single-track rm:tracks()); nil if the id is gone  @ 804
  @api rm:fxIds(id)  @ 816-826
      @contract  ordered live fx ids for a track via TrackFX — no chunk read; nil if the id is gone  @ 814
      @contract  second return: { [id] = ident } over the same chain  @ 815
  @api rm:reaperTrack(id)  @ 829-831
      @contract  raw MediaTrack handle for id — escape hatch for reaper ops rm doesn't model; nil if gone  @ 828
  @api rm:fxTrack(id)  @ 834-836
      @contract  live MediaTrack hosting fx id, resolved without reading its record/chunk; nil if gone  @ 833
  @api rm:masterId()  @ 839-842
      @contract  the master track's guid; resolves master without an rm:tracks() scan  @ 838
  @api rm:addTrack(t)  @ 844-864
  @api rm:assignTrack(id, t)  @ 866-872
  @api rm:deleteTrack(id)  @ 874-877
  @api rm:setSendGain(srcId, dstId, gain)  @ 881-892
      @contract  targeted live D_VOL on the audio send srcId→dstId; false if no such send is live.  @ 879
      @contract  the partial write assignTrack{sends} (full-replace) can't serve — for live gain pokes.  @ 880
  @api rm:addFx(trackId, t)  @ 894-908
  @api rm:assignFx(id, t)  @ 910-928
  @api rm:rewritePins(id, pinMaps)  @ 932-935
      -- Undo-free pin re-assert (no transaction; muted fx stash-divert may touch meta):
      -- repairs the identity-OR a same-cycle I_NCHAN grow stamps onto a just-written pin. See docs/wiringManager.md § Pin re-assert after grow.
  @api rm:meta(store, id)  @ 938-942
      @contract  read a named meta store ('fx'|'bus'): whole blob, or one entry when id given  @ 937
  @api rm:assignMeta(store, id, meta)  @ 945-947
      @contract  write a named meta store: nil deletes store[id], else patch-merge (util.REMOVE to clear)  @ 944
  @api rm:writeChainMidi(trackId, writes)  @ 951-976
      @contract  batch per-FX MIDI routing for one track in one chunk Get+Set; writes={{id,midi},...};  @ 949
      @contract  drops writes the cache says are current; all-unchanged skips the chunk read entirely  @ 950
  @api rm:deleteFx(id)  @ 978-981
  @api rm:fx(id)  @ 984-996
      @contract  fx record by id (ports, names, pinMaps, midi, trackId); nil if gone. Params separate.  @ 983
  @api rm:params(id)  @ 1000-1003
      @contract  live { [name] = value } param values for the fx by id; nil if gone.  @ 998
      @contract  the mutable control-state counterpart to the structural rm:fx record.  @ 999
  @api rm:setMuted(fxId, on)  @ 1008-1028
      @contract  silence/relight an fx. Muted: the silencing side's live pins are cleared  @ 1005
      @contract  (input for a processor, output for a generator), the real pinout stashed in  @ 1006
      @contract  fx-meta + reported up (wire kept); writes to that side divert to the stash.  @ 1007
  @api rm:muted(fxId)  @ 1031-1034
      @contract  true iff fxId is currently muted; false for a live or absent fx.  @ 1030
  @api rm:setBypassed(fxId, on)  @ 1037-1040
      @contract  bypass = REAPER-native FX enable (pass-through, topology-safe, not in the snapshot).  @ 1036
  @api rm:bypassed(fxId)  @ 1043-1046
      @contract  true iff fxId is bypassed (REAPER-disabled); false for an enabled or absent fx.  @ 1042
  @api rm:showFx(id)  @ 1049-1054
      @contract  floats the fx window for id; false if the fx is no longer live  @ 1048
  @api rm:installedFx()  @ 1058-1070
      @contract  enumerates reaper.EnumInstalledFX once, memoised; the set is runtime-fixed  @ 1056
      @contract  JS rows enumerate bare; their ident is canonicalised to the 'JS:' form  @ 1057
  @api rm:transaction(label, fn)  @ 1072-1078

